head.script:
scwin.screenId = "jldods17013";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods17013.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_usrStatNorm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_usrStatNorm_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_usrStatNorm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.usrStatNorm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17013.btn_usrStatNorm_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_list_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_list_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_list_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.list()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17013.btn_list_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_usrStatNorm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_usrStatNorm = async function () {
    const sbmOptions = {
        id: "tx_fn_usrStatNorm",
        method: "post",
        action: "/usradm/user.do",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods17013.tx_fn_usrStatNorm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/usradm/user.do",
        ref: "dma_loadListReq",
        target: "dlt_usradmFormUsrStatIdArr=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods17013.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = function () {
    /* sdd-asis-lifecycle:begin fn_list — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
    $('#ipt_method', $('#searchForm')).val("readUserList");
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.usrStatNorm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.usrStatNorm = function () {
    /* sdd-asis-lifecycle:begin fn_usrStatNorm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    confirmF('계정정지를 해제하시겠습니까?', function() {
            $('#ipt_usrStatId', $('#searchForm')).val("NORM");
            $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17013/jldods17013.xml");
            $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("03");
            $('#ipt_method', $('#searchForm')).val("updateUsrStatId");
            $.ajax({ type: "POST", url: "/usradm/user.do", data: $("#searchForm").serialize(), dataType: 'JSON', success: async function(data) {
                        if (data.result == 1) {
                            await alertE("계정정지가 해제 되었습니다.", async function() {
                                    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
                                    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
                                    $('#ipt_method', $('#searchForm')).val("readUserList");
                                    await scwin.tx_fn_usrStatNorm();
                            });
                        } else {
                            await alertE("상장법인의 총 사용자는 " + data.result + "명을 초과할 수 없습니다..");
                        }
                    }, error: async function(request, status, error) {
                        await alertE("계정정지 해제 처리에 실패하였습니다.\n시스템 담당자에게 문의하시기 바랍니다.");
                        return;
                    } });
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }
